<template>
  <div class="hub-page">
    <div class="hub-crumb">Workspace <span>/</span> {{ current.label }}</div>
    <header class="hub-header"><div><small>{{ current.eyebrow }}</small><h1>{{ current.title }}</h1><p>{{ current.description }}</p></div><nav aria-label="Insights tools"><router-link v-for="item in tabs.filter(entry => entry.to !== '/ai-insights')" :key="item.to" :to="item.to" :class="{active:route.path===item.to}">{{ item.short }}</router-link></nav></header>

    <section v-if="mode==='reports'" class="hub-stack">
      <div class="period-switch"><button :class="{active:days===7}" @click="days=7">This week</button><button :class="{active:days===30}" @click="days=30">This month</button></div>
      <div class="metric-grid"><article v-for="metric in reportMetrics" :key="metric.label"><span>{{ metric.icon }}</span><small>{{ metric.label }}</small><strong>{{ metric.value }}</strong><i>{{ metric.note }}</i></article></div>
      <article class="hub-card"><div class="card-title"><div><small>ACTIVITY MIX</small><h2>Your recorded momentum</h2></div><span>{{ report.recent }} total logs</span></div><div class="report-bars"><div v-for="metric in reportBars" :key="metric.label"><label><span>{{ metric.label }}</span><b>{{ metric.value }}</b></label><i><span :style="{width:metric.width+'%'}"></span></i></div></div></article>
      <article class="ai-callout"><span>✦</span><div><small>AI REVIEW</small><h2>Turn your records into a practical next step.</h2><p>Ask DLT to explain your current snapshot using the records already in your tracker.</p></div><router-link to="/ai-insights">Open AI insights →</router-link></article>
    </section>

    <section v-else-if="mode==='activity'" class="hub-card"><div class="card-title"><div><small>ALL MODULES</small><h2>Activity timeline</h2></div><select v-model="filter"><option>All</option><option v-for="type in timelineTypes" :key="type">{{ type }}</option></select></div><div class="timeline"><article v-for="item in filteredTimeline" :key="item.id"><span>{{ item.icon }}</span><div><strong>{{ item.title }}</strong><p>{{ item.detail }}</p></div><time>{{ item.dateKey || 'Date unavailable' }}</time></article><div v-if="!filteredTimeline.length" class="hub-empty">Your activity will appear here as you use the trackers.</div></div></section>

    <section v-else-if="mode==='search'" class="hub-stack">
      <article class="ai-search-card">
        <span class="ai-search-mark">✦</span>
        <div><small>ASK ACROSS YOUR WORKSPACE</small><h2>What do you want to know?</h2><p>Ask in English or Tagalog. DLT AI will use your recorded habits, goals, health, study, watchlist, calendar, and money data to answer.</p></div>
        <form @submit.prevent="askSearch"><div class="search-box"><span>⌕</span><input id="tracker-search" v-model="query" autofocus maxlength="1000" placeholder="e.g. What should I focus on today?" required><button :disabled="!query.trim()">Ask AI →</button></div></form>
        <div class="ai-search-prompts"><button v-for="prompt in searchPrompts" :key="prompt" @click="askSearch(prompt)">{{ prompt }}</button></div>
      </article>
      <article v-if="query && results.length" class="hub-card search-card"><div class="card-title"><div><small>RELATED RECORDS</small><h2>Quick links from your tracker</h2></div><span>{{ results.length }} matches</span></div><div class="search-results"><router-link v-for="(item,index) in results" :key="index" :to="item.to"><span>{{ item.type }}</span><div><strong>{{ item.title }}</strong><small>{{ item.detail }}</small></div><b>→</b></router-link></div></article>
    </section>

    <section v-else-if="mode==='notifications'" class="hub-card"><div class="card-title"><div><small>SMART REMINDERS</small><h2>Your notification center</h2></div><button class="quiet-btn" @click="toggleNotifications">{{ store.preferences.notifications ? 'Pause reminders' : 'Turn on reminders' }}</button></div><div v-if="store.preferences.notifications" class="notice-list"><router-link v-for="notice in notices" :key="notice.title+notice.detail" :to="notice.to"><span :class="notice.level">{{ notice.icon }}</span><div><strong>{{ notice.title }}</strong><p>{{ notice.detail }}</p></div><b>→</b></router-link></div><div v-else class="hub-empty">Reminders are paused. Your tracker data remains unchanged.</div></section>

    <section v-else-if="mode==='achievements'" class="achievement-grid"><article v-for="item in achievements" :key="item.name" :class="{unlocked:item.unlocked}"><span>{{ item.icon }}</span><small>{{ item.unlocked?'UNLOCKED':'IN PROGRESS' }}</small><h2>{{ item.name }}</h2><p>{{ item.detail }}</p><div><i><b :style="{width:item.progress+'%'}"></b></i><em>{{ item.value }} {{ item.unit }}</em></div></article></section>

    <section v-else-if="mode==='ai'" class="hub-stack"><article class="ai-hero"><div><small>TRACKER-AWARE GUIDANCE</small><h2>Ask about the day you actually recorded.</h2><p>DLT can review habits, goals, movement, hydration, study, check-ins, watchlist, and money totals. It treats missing entries as “not logged,” never as proof that you skipped something.</p><button @click="openAssistant">✦ Open DLT Assistant</button></div><div class="ai-orbit"><span>✦</span><i></i><b></b></div></article><div class="prompt-grid"><button v-for="prompt in aiPrompts" :key="prompt" @click="openAssistant">{{ prompt }} <span>↗</span></button></div><article class="hub-card privacy-note"><strong>Your privacy boundary</strong><p>Only a bounded tracker summary and recent conversation context are sent when you ask a question. Passwords, email addresses, and private reflections are excluded. The website does not accept document uploads.</p></article></section>

    <section v-else class="settings-grid">
      <article class="hub-card"><div class="card-title"><div><small>PROFILE</small><h2>Your account</h2></div><span class="sync-pill">● Firebase sync</span></div><label>Display name<input v-model="profileName" maxlength="60"></label><label>Email address<input :value="store.user?.email" disabled></label><button class="primary-btn" @click="saveProfile">Save profile</button><p v-if="saved" class="saved">✓ Changes saved</p></article>
      <article class="hub-card"><div class="card-title"><div><small>PREFERENCES</small><h2>Local experience</h2></div></div><label>Timezone<select v-model="draft.timezone"><option v-for="zone in zones" :key="zone">{{ zone }}</option></select></label><label>Currency<select v-model="draft.currency"><option>PHP</option><option>USD</option><option>EUR</option><option>SGD</option></select></label><label>Distance unit<select v-model="draft.distanceUnit"><option value="km">Kilometers</option><option value="mi">Miles</option></select></label></article>
      <article class="hub-card dashboard-settings"><div class="card-title"><div><small>CUSTOM DASHBOARD</small><h2>Choose what appears</h2></div></div><label v-for="item in dashboardOptions" :key="item.key"><span><strong>{{ item.label }}</strong><small>{{ item.detail }}</small></span><input type="checkbox" v-model="draft.dashboard[item.key]"></label></article>
      <article class="hub-card"><div class="card-title"><div><small>INSTALL</small><h2>Use DLT like an app</h2></div></div><p class="settings-copy">Install from your browser menu for a full-screen shortcut and cached app shell.</p><button class="primary-btn" @click="installApp" :disabled="!installPrompt">{{ installPrompt?'Install DLT':'Use “Add to Home Screen”' }}</button><button class="quiet-btn block" @click="saveSettings">Save all settings</button><p v-if="saved" class="saved">✓ Preferences saved and synced</p></article>
    </section>
  </div>
</template>

<script setup>
import { computed, reactive, ref, onMounted, onUnmounted } from 'vue'
import { useRoute } from 'vue-router'
import { useAppStore } from '../stores/appStore'
import { buildTimeline, buildNotifications, buildAchievements, reportSnapshot, searchTracker } from '../services/lifeInsights'
const store=useAppStore(), route=useRoute(); const days=ref(7), filter=ref('All'), query=ref(''), saved=ref(false), profileName=ref(store.username)
const tabs=[{to:'/reports',short:'Reports',label:'Reports',eyebrow:'YOUR PROGRESS',title:'Reports & patterns',description:'A clear view of what you recorded over time.'},{to:'/activity',short:'Timeline',label:'Activity',eyebrow:'ONE LIFE, ONE FEED',title:'Your activity timeline',description:'See records from every tracker in chronological order.'},{to:'/search',short:'Ask AI',label:'AI Search',eyebrow:'ASK ANYTHING',title:'Ask your whole tracker',description:'Get a useful answer from the records across your workspace.'},{to:'/notifications',short:'Alerts',label:'Notifications',eyebrow:'WHAT NEEDS ATTENTION',title:'Notification center',description:'Upcoming dates and helpful, optional reminders.'},{to:'/achievements',short:'Wins',label:'Achievements',eyebrow:'SMALL WINS ADD UP',title:'Achievements',description:'Celebrate consistency without turning life into a competition.'},{to:'/ai-insights',short:'AI',label:'AI Insights',eyebrow:'ASK YOUR TRACKER',title:'AI insights',description:'Use your current records to understand what to focus on.'},{to:'/settings',short:'Settings',label:'Settings',eyebrow:'MAKE IT YOURS',title:'Profile & settings',description:'Control your dashboard, preferences, sync, and installation.'}]
const mode=computed(()=>({reports:'reports',activity:'activity',search:'search',notifications:'notifications',achievements:'achievements','ai-insights':'ai',settings:'settings'}[String(route.name)]||'reports'))
const current=computed(()=>tabs.find(x=>x.to===route.path)||tabs[0]); const timeline=computed(()=>buildTimeline(store)); const timelineTypes=computed(()=>[...new Set(timeline.value.map(x=>x.type))]); const filteredTimeline=computed(()=>timeline.value.filter(x=>filter.value==='All'||x.type===filter.value).slice(0,80)); const notices=computed(()=>buildNotifications(store)); const achievements=computed(()=>buildAchievements(store)); const report=computed(()=>reportSnapshot(store,days.value)); const results=computed(()=>searchTracker(store,query.value))
const reportMetrics=computed(()=>[{icon:'✓',label:'Habit checkmarks',value:report.value.habitChecks,note:`Last ${days.value} days`},{icon:'⌁',label:'Movement',value:report.value.totalSteps.toLocaleString(),note:'Steps recorded'},{icon:'◌',label:'Average hydration',value:`${report.value.avgWater} ml`,note:'Per logged day'},{icon:'▤',label:'Focused reading',value:`${report.value.studyMinutes} min`,note:'Reading sessions'},{icon:'♡',label:'Daily check-ins',value:report.value.checkins,note:`of ${days.value} days`},{icon:'₱',label:'Expenses',value:`₱${report.value.expenses.toLocaleString()}`,note:'Recorded spending'}]); const reportBars=computed(()=>reportMetrics.value.slice(0,5).map((x,i)=>({...x,width:Math.min(100,[report.value.habitChecks/(days.value*3),report.value.totalSteps/(days.value*store.fitnessStepGoal),report.value.avgWater/store.waterDailyTarget,report.value.studyMinutes/(days.value*30),report.value.checkins/days.value][i]*100||0)})))
const draft=reactive(JSON.parse(JSON.stringify(store.preferences))); const dashboardOptions=[{key:'metrics',label:'Daily metrics',detail:'Today’s headline numbers'},{key:'progress',label:'Progress chart',detail:'Tabbed tracker chart'},{key:'work',label:'Work sessions',detail:'Recent time logs'},{key:'sidePanel',label:'Daily side panel',detail:'Focus and quick context'},{key:'trends',label:'30-day trends',detail:'Movement and savings charts'},{key:'discover',label:'Recommendations',detail:'Check-in, study, and watchlist prompts'}]; const zones=['Asia/Manila','Asia/Singapore','UTC','America/New_York','Europe/London']; const aiPrompts=['How am I doing today?','What have I not logged?','Which goal needs attention?','Explain my recent progress.']; const searchPrompts=['What did I forget today?','Summarize my week','How is my budget doing?','Which goal needs attention?']; let installPrompt=ref(null)
async function saveProfile(){await store.updateProfileName(profileName.value); saved.value=true;setTimeout(()=>saved.value=false,2000)} async function saveSettings(){await store.updatePreferences(JSON.parse(JSON.stringify(draft)));saved.value=true;setTimeout(()=>saved.value=false,2000)} async function toggleNotifications(){await store.updatePreferences({notifications:!store.preferences.notifications});draft.notifications=store.preferences.notifications} function openAssistant(){window.dispatchEvent(new Event('dlt-open-assistant'))} function askSearch(prompt=query.value){const text=String(prompt||'').trim();if(!text)return;query.value=text;window.dispatchEvent(new CustomEvent('dlt-open-assistant',{detail:{prompt:text}}))} function captureInstall(e){e.preventDefault();installPrompt.value=e} async function installApp(){if(!installPrompt.value)return;await installPrompt.value.prompt();installPrompt.value=null} onMounted(()=>window.addEventListener('beforeinstallprompt',captureInstall));onUnmounted(()=>window.removeEventListener('beforeinstallprompt',captureInstall))
</script>

